+        if (selectedRadio) {
+            const preference = selectedRadio.value;
+            console.log('Notification preference saved:', preference);
+            
+            successMessage.style.display = 'block';
+            
+            setTimeout(() => {
+                successMessage.style.display = 'none';
+            }, 3000);
+        }
+    });
+});
